// PreloadCount sets a count in the C struct by name
func (o *User) PreloadCount(name string, count int64) error {
	if o == nil {
		return nil
	}

	switch name {
	case "CreatedByAPITokens":
		o.C.CreatedByAPITokens = &count
	case "ApprovedByApprovals":
		o.C.ApprovedByApprovals = &count
	case "RequestedByApprovals":
		o.C.RequestedByApprovals = &count
	case "ProjectMembers":
		o.C.ProjectMembers = &count
	case "Sessions":
		o.C.Sessions = &count
	case "RequestedByTaskRuns":
		o.C.RequestedByTaskRuns = &count
	}
	return nil
}

