type userJoins[Q dialect.Joinable] struct {
	typ                  string
	CreatedByAPITokens   modAs[Q, apiTokenColumns]
	ApprovedByApprovals  modAs[Q, approvalColumns]
	RequestedByApprovals modAs[Q, approvalColumns]
	ProjectMembers       modAs[Q, projectMemberColumns]
	Sessions             modAs[Q, sessionColumns]
	RequestedByTaskRuns  modAs[Q, taskRunColumns]
}

func (j userJoins[Q]) aliasedAs(alias string) userJoins[Q] {
	return buildUserJoins[Q](buildUserColumns(alias), j.typ)
}

func buildUserJoins[Q dialect.Joinable](cols userColumns, typ string) userJoins[Q] {
	return userJoins[Q]{
		typ: typ,
		CreatedByAPITokens: modAs[Q, apiTokenColumns]{
			c: APITokens.Columns,
			f: func(to apiTokenColumns) bob.Mod[Q] {
				mods := make(mods.QueryMods[Q], 0, 1)

				{
					mods = append(mods, dialect.Join[Q](typ, APITokens.NameExpr().As(to.Alias())).On(
						to.CreatedBy.EQ(cols.ID),
					))
				}

				return mods
			},
		},
		ApprovedByApprovals: modAs[Q, approvalColumns]{
			c: Approvals.Columns,
			f: func(to approvalColumns) bob.Mod[Q] {
				mods := make(mods.QueryMods[Q], 0, 1)

				{
					mods = append(mods, dialect.Join[Q](typ, Approvals.NameExpr().As(to.Alias())).On(
						to.ApprovedBy.EQ(cols.ID),
					))
				}

				return mods
			},
		},
		RequestedByApprovals: modAs[Q, approvalColumns]{
			c: Approvals.Columns,
			f: func(to approvalColumns) bob.Mod[Q] {
				mods := make(mods.QueryMods[Q], 0, 1)

				{
					mods = append(mods, dialect.Join[Q](typ, Approvals.NameExpr().As(to.Alias())).On(
						to.RequestedBy.EQ(cols.ID),
					))
				}

				return mods
			},
		},
		ProjectMembers: modAs[Q, projectMemberColumns]{
			c: ProjectMembers.Columns,
			f: func(to projectMemberColumns) bob.Mod[Q] {
				mods := make(mods.QueryMods[Q], 0, 1)

				{
					mods = append(mods, dialect.Join[Q](typ, ProjectMembers.NameExpr().As(to.Alias())).On(
						to.UserID.EQ(cols.ID),
					))
				}

				return mods
			},
		},
		Sessions: modAs[Q, sessionColumns]{
			c: Sessions.Columns,
			f: func(to sessionColumns) bob.Mod[Q] {
				mods := make(mods.QueryMods[Q], 0, 1)

				{
					mods = append(mods, dialect.Join[Q](typ, Sessions.NameExpr().As(to.Alias())).On(
						to.UserID.EQ(cols.ID),
					))
				}

				return mods
			},
		},
		RequestedByTaskRuns: modAs[Q, taskRunColumns]{
			c: TaskRuns.Columns,
			f: func(to taskRunColumns) bob.Mod[Q] {
				mods := make(mods.QueryMods[Q], 0, 1)

				{
					mods = append(mods, dialect.Join[Q](typ, TaskRuns.NameExpr().As(to.Alias())).On(
						to.RequestedBy.EQ(cols.ID),
					))
				}

				return mods
			},
		},
	}
}
